window.DNA_CHAIN_ENGINE = (function() {
  "use strict";

  function normalizeStateTag(tag) {
    return String(tag || "").toLowerCase().trim();
  }

  function statesMatch(outTag, reqTag) {
    var o = normalizeStateTag(outTag);
    var r = normalizeStateTag(reqTag);
    if (!o || !r) return false;
    if (o === r || o.indexOf(r) !== -1 || r.indexOf(o) !== -1) return true;
    if ((r.indexOf("arts_reaction") !== -1 || r.indexOf("reaction") !== -1) &&
        (o.indexOf("combustion") !== -1 || o.indexOf("solidification") !== -1 ||
         o.indexOf("electrification") !== -1 || o.indexOf("corrosion") !== -1 ||
         o.indexOf("shatter") !== -1 || o.indexOf("reaction") !== -1)) return true;
    if ((r.indexOf("vulnerability") !== -1 || r.indexOf("physical") !== -1) &&
        (o.indexOf("vulnerability") !== -1 || o.indexOf("lift") !== -1 ||
         o.indexOf("knock_down") !== -1 || o.indexOf("crush") !== -1 || o.indexOf("breach") !== -1)) return true;
    if (r.indexOf("infliction") !== -1 && o.indexOf("infliction") !== -1) {
      var elems = ["heat", "cryo", "electric", "nature"];
      for (var i = 0; i < elems.length; i++) {
        if (r.indexOf(elems[i]) !== -1 && o.indexOf(elems[i]) !== -1) return true;
      }
      if (r === "arts_infliction" || r.indexOf("any") !== -1) return true;
    }
    if (r.indexOf("final_strike") !== -1) return true;
    return false;
  }

  function getAgentAllOutputStates(agent) {
    if (!agent || !agent.dna) return ["final_strike"];
    var outs = ["final_strike"];
    var tOut = agent.dna.triggersOut || [];
    var fOut = (agent.dna.comboFollowUpOut && agent.dna.comboFollowUpOut.nextStates) ? agent.dna.comboFollowUpOut.nextStates : [];
    for (var i = 0; i < tOut.length; i++) outs.push(tOut[i]);
    for (var j = 0; j < fOut.length; j++) outs.push(fOut[j]);
    return outs;
  }

  function scoreCandidateWithSquad(candidate, currentSquadAgents) {
    if (!candidate) return { score: 0, reasons: [] };
    if (!currentSquadAgents || currentSquadAgents.length === 0) {
      return { score: candidate.tier === "SS" ? 98 : 90, reasons: ["Лидер отряда"] };
    }

    var score = 52;
    var reasons = [];
    var candOuts = getAgentAllOutputStates(candidate);
    var candReqs = (candidate.dna && candidate.dna.comboTriggerIn && candidate.dna.comboTriggerIn.requiredStates)
      ? candidate.dna.comboTriggerIn.requiredStates : [];

    // 1. Direct partner list match
    for (var i = 0; i < currentSquadAgents.length; i++) {
      var mate = currentSquadAgents[i];
      if (!mate) continue;
      var matePartners = mate.bestPartners || [];
      for (var p = 0; p < matePartners.length; p++) {
        var pid = matePartners[p].partnerId || matePartners[p].id;
        if (pid === candidate.id) {
          var synVal = matePartners[p].synergyPct || matePartners[p].synergy || 94;
          score = Math.max(score, synVal - 4);
          reasons.push("Идеальная связка с " + mate.nameRu);
        }
      }
      var candPartners = candidate.bestPartners || [];
      for (var cp = 0; cp < candPartners.length; cp++) {
        var cpid = candPartners[cp].partnerId || candPartners[cp].id;
        if (cpid === mate.id) {
          var csynVal = candPartners[cp].synergyPct || candPartners[cp].synergy || 94;
          score = Math.max(score, csynVal - 4);
        }
      }
    }

    // 2. Does squad trigger candidate's combo?
    var triggeredByMate = false;
    for (var m = 0; m < currentSquadAgents.length; m++) {
      var mOuts = getAgentAllOutputStates(currentSquadAgents[m]);
      for (var r = 0; r < candReqs.length; r++) {
        for (var o = 0; o < mOuts.length; o++) {
          if (statesMatch(mOuts[o], candReqs[r])) {
            triggeredByMate = true;
            break;
          }
        }
      }
    }
    if (triggeredByMate) {
      score += 14;
      reasons.push("Комбо активируется союзниками");
    }

    // 3. Does candidate trigger squadmates' combos?
    var triggersMate = false;
    for (var m2 = 0; m2 < currentSquadAgents.length; m2++) {
      var mateReqs = (currentSquadAgents[m2].dna && currentSquadAgents[m2].dna.comboTriggerIn)
        ? (currentSquadAgents[m2].dna.comboTriggerIn.requiredStates || []) : [];
      for (var r2 = 0; r2 < mateReqs.length; r2++) {
        for (var o2 = 0; o2 < candOuts.length; o2++) {
          if (statesMatch(candOuts[o2], mateReqs[r2])) {
            triggersMate = true;
            break;
          }
        }
      }
    }
    if (triggersMate) {
      score += 14;
      reasons.push("Запускает Цепочку Атак отряда");
    }

    // 4. Element / SP economy balance
    var leader = currentSquadAgents[0];
    if (leader && leader.elementId === candidate.elementId) {
      score += 8;
    }
    if (candidate.classId === "Vanguard" || candidate.classId === "Supporter" || candidate.classId === "Defender") {
      score += 6;
    }

    score = Math.min(99, Math.max(45, Math.round(score)));
    return { score: score, reasons: reasons };
  }

  function autoBuildOptimalSquad(leaderId, availablePool) {
    var pool = availablePool || window.DB_CHARACTERS || [];
    var leader = null;
    for (var i = 0; i < pool.length; i++) {
      if (pool[i].id === leaderId) { leader = pool[i]; break; }
    }
    if (!leader && pool.length > 0) leader = pool[0];
    if (!leader) return [null, null, null, null];

    var chosen = [leader];
    var usedIds = {};
    usedIds[leader.id] = true;

    for (var slot = 1; slot < 4; slot++) {
      var bestCand = null;
      var bestScore = -1;
      for (var j = 0; j < pool.length; j++) {
        var cand = pool[j];
        if (usedIds[cand.id]) continue;
        var s = scoreCandidateWithSquad(cand, chosen).score;
        // Prefer role diversity for slot 2 (Sub-DPS/Enabler), slot 3 (Supporter), slot 4 (Vanguard/Defender/Sustain)
        if (slot === 2 && (cand.classId === "Supporter" || cand.classId === "Caster")) s += 5;
        if (slot === 3 && (cand.classId === "Vanguard" || cand.classId === "Defender" || cand.classId === "Supporter")) s += 6;
        if (s > bestScore) {
          bestScore = s;
          bestCand = cand;
        }
      }
      if (bestCand) {
        chosen.push(bestCand);
        usedIds[bestCand.id] = true;
      }
    }

    return [
      chosen[0] ? chosen[0].id : null,
      chosen[1] ? chosen[1].id : null,
      chosen[2] ? chosen[2].id : null,
      chosen[3] ? chosen[3].id : null
    ];
  }

  function evaluateSquadChain(squadAgents, potentials) {
    var active = (squadAgents || []).filter(Boolean);
    if (active.length === 0) {
      return { totalSynergyPct: 0, chainLinks: [], spEconomyText: "Отряд пуст", activeBuffs: [], rotationSteps: [] };
    }

    var chainLinks = [];
    var triggeredCount = 0;
    var spNet = 0;
    var activeBuffs = [];

    for (var i = 0; i < active.length; i++) {
      var ag = active[i];
      var pot = (potentials && potentials[i]) ? potentials[i] : 0;
      spNet += (ag.dna && typeof ag.dna.spEconomy === "number") ? ag.dna.spEconomy : 0;
      var buffs = (ag.dna && ag.dna.buffOutVector) ? ag.dna.buffOutVector : [];
      for (var b = 0; b < buffs.length; b++) {
        activeBuffs.push(ag.nameRu + (pot > 0 ? " (P" + pot + ")" : "") + ": " + buffs[b]);
      }

      var reqs = (ag.dna && ag.dna.comboTriggerIn && ag.dna.comboTriggerIn.requiredStates)
        ? ag.dna.comboTriggerIn.requiredStates : [];
      var condText = (ag.dna && ag.dna.comboTriggerIn && ag.dna.comboTriggerIn.conditionTextRu)
        ? ag.dna.comboTriggerIn.conditionTextRu : "Активация по условию боя";
      var followText = (ag.dna && ag.dna.comboFollowUpOut && ag.dna.comboFollowUpOut.effectTextRu)
        ? ag.dna.comboFollowUpOut.effectTextRu : "Продолжает цепочку урона и стаггера";

      var triggeredByNames = [];
      for (var m = 0; m < active.length; m++) {
        var mate = active[m];
        var mOuts = getAgentAllOutputStates(mate);
        var matched = false;
        for (var r = 0; r < reqs.length; r++) {
          for (var o = 0; o < mOuts.length; o++) {
            if (statesMatch(mOuts[o], reqs[r])) {
              matched = true;
              break;
            }
          }
          if (matched) break;
        }
        if (matched && triggeredByNames.indexOf(mate.nameRu) === -1) {
          triggeredByNames.push(mate.nameRu);
        }
      }

      var isTrig = triggeredByNames.length > 0;
      if (isTrig) triggeredCount++;
      chainLinks.push({
        agent: ag,
        isTriggered: isTrig,
        triggeredByNames: triggeredByNames,
        conditionTextRu: condText,
        followUpTextRu: followText
      });
    }

    var pairScores = [];
    for (var x = 0; x < active.length; x++) {
      var others = active.filter(function(_, idx) { return idx !== x; });
      if (others.length > 0) {
        pairScores.push(scoreCandidateWithSquad(active[x], others).score);
      } else {
        pairScores.push(90);
      }
    }
    var avgPair = pairScores.reduce(function(a, b){ return a + b; }, 0) / pairScores.length;
    var triggerBonus = Math.round((triggeredCount / active.length) * 10);
    var totalSynergyPct = Math.min(99, Math.max(50, Math.round(avgPair * 0.9 + triggerBonus)));

    var spText = spNet >= 0
      ? "Положительный баланс SP (+" + spNet + " индекс генерации): отряд свободно прокручивает Боевые навыки по КД без простоев."
      : "Агрессивный расход SP (" + spNet + "): обязательно завершайте серии обычных атак Финальным ударом (Final Strike) и добивайте оглушённых врагов Финишером.";

    var rotationSteps = [];
    var leader = active[0];
    var sup = active[2] || active[1] || leader;
    var sub = active[1] || leader;
    var van = active[3] || active[1] || leader;

    rotationSteps.push("Инициация и заливка SP (" + van.nameRu + " + " + sup.nameRu + "): начните с Боевого навыка или стойки " + sup.nameRu + ", наложите первичный статус/инфликцию и проведите серию до Финального удара (Final Strike).");
    rotationSteps.push("Запуск Каскада Цепочки Атак (" + sub.nameRu + " ➔ " + leader.nameRu + "): как только сработает триггер состояния, мгновенно прожмите вспыхнувшие кнопки Комбо-навыков (Combo Skills) без траты SP!");
    rotationSteps.push("Накопление Оглушения (Stagger Break) и Амплификация: используйте Комбо-атаки и дебаффы (" + sup.nameRu + ") для заполнения полоски Stagger босса и наложения Уязвимости / Восприимчивости.");
    rotationSteps.push("Окно Максимального Бурста (" + leader.nameRu + "): проведите Финишер по оглушённому врагу и разрядите Сверхспособность (Ульту) " + leader.nameRu + " под всеми активными баффами отряда!");

    return {
      totalSynergyPct: totalSynergyPct,
      chainLinks: chainLinks,
      spEconomyText: spText,
      activeBuffs: activeBuffs,
      rotationSteps: rotationSteps
    };
  }

  return {
    scoreCandidateWithSquad: scoreCandidateWithSquad,
    autoBuildOptimalSquad: autoBuildOptimalSquad,
    evaluateSquadChain: evaluateSquadChain
  };
})();
